// Claude AI chat — uses local `claude` CLI via stdin (no API key required)
const { spawn } = require('child_process');

app.post('/api/ai/chat', (req, res) => {
  res.setTimeout(0); // No timeout — allow complex long-running requests
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  // Use stdin to avoid OS argument length limits; -p without an argument reads from stdin
  const proc = spawn(claudePath, ['-p'], {
    env: childEnv,
  });

  let output = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => { output += data.toString(); });
  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  proc.on('close', (code) => {
    if (code !== 0) {
      return res.status(500).json({ error: errOutput.trim() || `claude exited with code ${code}` });
    }
    res.json({ content: output.trim() });
  });

  proc.on('error', (err) => {
    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
  });

  // Write prompt via stdin and close
  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();
});

// Claude AI chat — streaming SSE variant
app.post('/api/ai/stream', (req, res) => {
  res.setTimeout(0);
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';

  proc.stdout.on('data', (data) => {
    const chunk = data.toString();
    fullOutput += chunk;
    res.write(`data: ${JSON.stringify({ type: 'chunk', content: chunk })}\n\n`);
  });

  proc.stderr.on('data', () => {});

  proc.on('close', (code) => {
    if (code !== 0) {
      res.write(`data: ${JSON.stringify({ type: 'error', error: 'Claude process failed' })}\n\n`);
    } else {
      res.write(`data: ${JSON.stringify({ type: 'done', content: fullOutput.trim() })}\n\n`);
    }
    res.end();
  });

  proc.on('error', (err) => {
    res.write(`data: ${JSON.stringify({ type: 'error', error: err.message })}\n\n`);
    res.end();
  });

  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();

  req.on('close', () => { try { proc.kill(); } catch {} });
});

