      const isError = finalOutput.startsWith('Error:')
      setHistory(prev => [{
        id: `${Date.now()}`,
        agent: selectedAgent || 'No Agent',
        prompt: prompt.trim(),
        output: finalOutput,
        duration,
        status: isError ? 'error' : 'success',
        timestamp: new Date(),
      }, ...prev].slice(0, 20))

