// ─── Main Page ───────────────────────────────────────────────────────────────

export default function Setup() {
  const { data: status, loading: statusLoading, refetch: refetchStatus } = useApi(getSetupStatus)
  const { data: projects, loading: projectsLoading, refetch: refetchProjects } = useApi(getSetupProjects)
  const [installingPaths, setInstallingPaths] = useState<Set<string>>(new Set())

  const pm2Map: Record<string, { label: string; status: 'ok' | 'warn' | 'error'; note: string }> = {
    online:         { label: 'Running',        status: 'ok',    note: 'Claude Hub is running as a background service. All agents and APIs are available.' },
    stopped:        { label: 'Stopped',        status: 'warn',  note: 'Claude Hub is stopped. Run: pm2 restart claude-hub' },
    errored:        { label: 'Errored',        status: 'error', note: 'Claude Hub crashed. Check logs: pm2 logs claude-hub' },
    not_registered: { label: 'Not Registered', status: 'warn',  note: 'pm2 is installed but Claude Hub is not registered. Run: pm2 start ecosystem.config.js && pm2 save' },
    not_installed:  { label: 'Not Installed',  status: 'error', note: 'pm2 is not installed. Run: npm install -g pm2' },
    unknown:        { label: 'Unknown',        status: 'warn',  note: 'Could not determine pm2 status.' },
  }
  const pm2Info = pm2Map[status?.pm2Status ?? 'unknown'] ?? pm2Map.unknown

  async function handleInstallSdk(projectPath: string) {
    setInstallingPaths(prev => new Set(prev).add(projectPath))
    try {
      const res = await fetch('/api/setup/install-sdk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectPath }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Install failed')
      toast('success', `SDK installed in ${projectPath.split('/').pop()}`)
      refetchProjects()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Install failed')
    } finally {
      setInstallingPaths(prev => { const n = new Set(prev); n.delete(projectPath); return n })
    }
  }

  const allGreen = status && status.pm2Status === 'online' && status.launchAgentInstalled && status.agentCount > 0 && status.sdkExists
  const projectsAllGood = projects?.every(p => p.hasSdk && p.hasPackageEntry)

  return (
    <div className="p-8 max-w-4xl space-y-10">

      {/* ── Header ── */}
      <div>
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2.5 bg-accent-muted rounded-xl border border-accent/20">
            <Wrench className="w-5 h-5 text-accent" />
          </div>
          <div>
            <h1 className="text-xl font-semibold tracking-tight">Setup & Status</h1>
            <p className="text-xs text-text-muted mt-0.5">Full system status, SDK management, agent reference, and setup guide</p>
          </div>
        </div>

        {allGreen && projectsAllGood && (
          <div className="mt-4 flex items-center gap-2.5 px-4 py-3 bg-green-muted border border-green/20 rounded-xl">
            <CheckCircle className="w-4 h-4 text-green shrink-0" />
            <p className="text-xs text-green font-medium">All systems operational — Claude Hub is running, all agents loaded, SDK installed in all projects.</p>
          </div>
        )}
      </div>

      {/* ── Section 1: System Health ── */}
      <section>
        <div className="flex items-center justify-between mb-1">
          <SectionHeader icon={Cpu} title="System Health" subtitle="Live status of every component. Click Refresh to update." />
          <button onClick={() => { refetchStatus(); refetchProjects() }} className="flex items-center gap-1.5 text-xs text-text-muted hover:text-text transition-colors mb-5">
            <RefreshCw className="w-3.5 h-3.5" /> Refresh
          </button>
        </div>

        {statusLoading ? (
          <div className="grid grid-cols-2 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="h-28 bg-surface border border-border rounded-xl animate-pulse" />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            <StatusCard
              icon={Zap}
              title="Claude Hub Service (pm2)"
              status={pm2Info.status}
              statusLabel={pm2Info.label}
              detail={status ? `localhost:${status.port}` : undefined}
              note={pm2Info.note}
              action={status?.pm2Status !== 'online' ? (
                <div className="space-y-2">
                  <p className="text-[11px] text-text-muted font-medium">Fix command:</p>
                  <CodeBlock code={
                    status?.pm2Status === 'not_installed'
                      ? 'npm install -g pm2\ncd ~/Desktop/Boldteq\\ App/claude-hub\npm2 start ecosystem.config.js\npm2 save'
                      : status?.pm2Status === 'not_registered'
                      ? 'cd ~/Desktop/Boldteq\\ App/claude-hub\npm2 start ecosystem.config.js\npm2 save'
                      : 'pm2 restart claude-hub'
                  } />
                </div>
              ) : undefined}
            />

            <StatusCard
              icon={RefreshCw}
              title="Auto-Start on Login (LaunchAgent)"
              status={status?.launchAgentInstalled ? 'ok' : 'error'}
              statusLabel={status?.launchAgentInstalled ? 'Enabled' : 'Not Configured'}
              detail="~/Library/LaunchAgents/io.boldteq.claude-hub.plist"
              note={
                status?.launchAgentInstalled
                  ? 'Claude Hub starts automatically when you log into your Mac. No manual steps needed.'
                  : 'LaunchAgent plist not found. Claude Hub will NOT start on login — you must start it manually each session.'
              }
              action={!status?.launchAgentInstalled ? (
                <div className="space-y-2">
                  <p className="text-[11px] text-text-muted font-medium">The plist file must exist first, then load it:</p>
                  <CodeBlock code={`launchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist\n# Verify:\nlaunchctl list | grep claude-hub`} />
                </div>
              ) : undefined}
            />

            <StatusCard
              icon={Bot}
              title="Global Agents"
              status={(status?.agentCount ?? 0) >= 12 ? 'ok' : (status?.agentCount ?? 0) > 0 ? 'warn' : 'error'}
              statusLabel={
                (status?.agentCount ?? 0) > 0
                  ? `${status?.agentCount} / 12 agents loaded`
                  : 'No agents found'
              }
              detail="~/.claude/agents/"
              note={
                (status?.agentCount ?? 0) >= 12
                  ? 'All 12 global agents are loaded and available in every Claude Code session.'
                  : (status?.agentCount ?? 0) > 0
                  ? `Only ${status?.agentCount} agents found. Expected 12 — some may be missing from ~/.claude/agents/.`
                  : 'No agent files found in ~/.claude/agents/. Agents are not available.'
              }
              action={(status?.agentCount ?? 0) < 12 ? (
                <CodeBlock code={`ls ~/.claude/agents/\n# Expected: arya.md bolt.md hawk.md koda.md luna.md\n#           mira.md nova.md quill.md rex.md riko.md sage.md vex.md`} />
              ) : undefined}
            />

            <StatusCard
              icon={Package}
              title="Agent SDK (@boldteq/agents)"
              status={status?.sdkExists ? 'ok' : 'error'}
              statusLabel={status?.sdkExists ? 'Ready' : 'Missing'}
              detail="claude-hub/sdk/  (index.js + index.d.ts + package.json)"
              note={
                status?.sdkExists
                  ? 'The shared SDK package exists. Any project can install it via: "file:../claude-hub/sdk" in package.json.'
                  : 'SDK folder missing. The sdk/ directory must exist in claude-hub/ with index.js, index.d.ts, and package.json.'
              }
            />
          </div>
        )}
      </section>

      {/* ── Section 2: Project SDK Status ── */}
      <section>
        <SectionHeader
          icon={Folder}
          title="Project SDK Status"
          subtitle='Shows whether @boldteq/agents is installed in each project. "SDK Installed" means node_modules is ready. "package.json Entry" means it\'s listed as a dependency.'
        />

        <NoteBox type="info">
          <strong>Why this matters:</strong> Each project needs the SDK installed to call agents programmatically via <code className="font-mono text-accent">callAgent()</code>. If "SDK Installed" is red, click Install — it adds the entry to package.json and runs npm install automatically.
        </NoteBox>

        <div className="mt-4">
          {projectsLoading ? (
            <div className="bg-surface border border-border rounded-xl p-6 animate-pulse h-40" />
          ) : !projects || projects.length === 0 ? (
            <div className="bg-surface border border-border rounded-xl p-8 text-center">
              <Folder className="w-8 h-8 text-text-muted mx-auto mb-2" />
              <p className="text-sm text-text-secondary font-medium">No projects found</p>
              <p className="text-xs text-text-muted mt-1">Add project directories in <strong>Settings</strong> so Claude Hub can discover them.</p>
            </div>
          ) : (
            <div className="bg-surface border border-border rounded-xl overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-border bg-surface-2">
                    <th className="text-left px-5 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">Project</th>
                    <th className="text-center px-4 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">SDK Installed</th>
                    <th className="text-center px-4 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">package.json Entry</th>
                    <th className="px-4 py-3" />
                  </tr>
                </thead>
                <tbody>
                  {projects.map((p, i) => {
                    const isInstalling = installingPaths.has(p.path)
                    const needsInstall = !p.hasSdk || !p.hasPackageEntry
                    return (
                      <tr key={p.path} className={`${i < projects.length - 1 ? 'border-b border-border' : ''} hover:bg-surface-2 transition-colors`}>
                        <td className="px-5 py-3.5">
                          <p className="font-medium text-sm">{p.name}</p>
                          <p className="text-[11px] text-text-muted font-mono mt-0.5">{p.path.replace('/Users/yashbaldha', '~')}</p>
                        </td>
                        <td className="px-4 py-3.5 text-center">
                          <StatusBadge ok={p.hasSdk} label={p.hasSdk ? 'Installed' : 'Missing'} />
                        </td>
                        <td className="px-4 py-3.5 text-center">
                          <StatusBadge ok={p.hasPackageEntry} label={p.hasPackageEntry ? 'Yes' : 'No'} />
                        </td>
                        <td className="px-4 py-3.5 text-right">
                          {needsInstall && (
                            <button
                              disabled={isInstalling}
                              onClick={() => handleInstallSdk(p.path)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-accent text-white rounded-lg hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                            >
                              {isInstalling ? <><RefreshCw className="w-3 h-3 animate-spin" /> Installing...</> : <><Package className="w-3 h-3" /> Install SDK</>}
                            </button>
                          )}
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </section>

      {/* ── Section 3: Agent Roster ── */}
      <section>
        <SectionHeader
          icon={Bot}
          title="Global Agent Roster"
          subtitle="All 12 agents in ~/.claude/agents/ — loaded automatically in every Claude Code session."
        />

        <NoteBox type="info">
          <strong>How agents work:</strong> Claude Code loads all .md files from <code className="font-mono text-accent">~/.claude/agents/</code> at the start of every session. You can invoke any agent by mentioning its name in chat, or Claude will route automatically based on the task type. Agents can also be called programmatically via the SDK.
        </NoteBox>

        <div className="mt-4 bg-surface border border-border rounded-xl overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border bg-surface-2">
                <th className="text-left px-5 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">Agent File</th>
                <th className="text-left px-4 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">Name</th>
                <th className="text-left px-4 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider w-16">Model</th>
                <th className="text-left px-4 py-3 text-[11px] font-semibold text-text-muted uppercase tracking-wider">When to Use</th>
              </tr>
            </thead>
            <tbody>
              {AGENTS.map((a, i) => (
                <tr key={a.file} className={`${i < AGENTS.length - 1 ? 'border-b border-border' : ''} hover:bg-surface-2 transition-colors`}>
                  <td className="px-5 py-3">
                    <code className="text-xs font-mono text-accent bg-accent-muted px-2 py-0.5 rounded">{a.file}</code>
                  </td>
                  <td className="px-4 py-3">
                    <p className="text-xs font-medium text-text">{a.name}</p>
                  </td>
                  <td className="px-4 py-3">
                    <span className={`text-[10px] font-mono px-1.5 py-0.5 rounded ${a.model === 'opus' ? 'bg-purple-muted text-purple' : 'bg-surface-2 text-text-muted'}`}>
                      {a.model}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <p className="text-xs text-text-muted leading-relaxed">{a.use}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="mt-4 grid grid-cols-2 gap-4">
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3">Standard Build Flow</p>
            {['nova → Research market', 'arya → Design architecture', 'riko → Scaffold project', 'koda → Build features', 'luna → Write tests', 'sage → Review code', 'bolt → Deploy', 'mira → Extract lessons'].map((step, i) => (
              <div key={step} className="flex items-center gap-2.5 text-xs text-text-secondary">
                <span className="w-4 h-4 rounded-full bg-accent/20 text-accent text-[10px] flex items-center justify-center font-bold shrink-0">{i + 1}</span>
                <span className="font-mono">{step}</span>
              </div>
            ))}
          </div>
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3">Quick Task Routing</p>
            {[
              ['Bug / error', 'vex'],
              ['New feature', 'koda'],
              ['Content / copy', 'quill'],
              ['Research', 'nova'],
              ['Architecture', 'arya'],
              ['Tests', 'luna'],
              ['Pre-deploy', 'sage'],
              ['Deploy', 'bolt'],
            ].map(([task, agent]) => (
              <div key={task} className="flex items-center justify-between text-xs">
                <span className="text-text-muted">{task}</span>
                <code className="text-accent font-mono bg-accent-muted px-1.5 py-0.5 rounded text-[10px]">{agent}</code>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Section 4: SDK Usage ── */}
      <section>
        <SectionHeader
          icon={Code}
          title="@boldteq/agents SDK"
          subtitle="Call any agent from any Boldteq app. Zero cost — uses your existing Claude subscription."
        />

        <NoteBox type="tip">
          <strong>How it works:</strong> Your app calls <code className="font-mono text-accent">callAgent()</code> → hits Claude Hub at localhost:3847 → Claude Hub loads the agent's .md instructions → runs <code className="font-mono text-accent">claude -p</code> → streams the result back. No API keys needed in your app.
        </NoteBox>

        <div className="mt-4 space-y-4">
          <Collapsible title="Basic Usage (TypeScript / JavaScript)" defaultOpen>
            <CodeBlock lang="typescript" code={`import { callAgent } from '@boldteq/agents'

// Call any agent with a task
const result = await callAgent('quill', 'Write App Store listing for Pinzo')

if (result.success) {
  console.log(result.output)   // The agent's response
} else {
  console.error(result.error)  // e.g. "Claude Hub not reachable"
}`} />
            <NoteBox type="info">
              <strong>Server-only:</strong> The SDK calls localhost:3847 — only works in server-side code (loaders, actions, API routes, Edge Functions). Never import it in browser/client code.
            </NoteBox>
          </Collapsible>

          <Collapsible title="All Available Functions">
            <div className="space-y-4">
              <div>
                <p className="text-xs font-semibold text-text-secondary mb-2">callAgent(agentName, prompt, timeoutMs?)</p>
                <CodeBlock lang="typescript" code={`const result = await callAgent('vex', 'Fix: TypeError cannot read property of undefined in delivery-rules.tsx')
// Returns: { success: boolean, output: string, agent: string, error?: string }`} />
              </div>
              <div>
                <p className="text-xs font-semibold text-text-secondary mb-2">listAgents() — get all available agents</p>
                <CodeBlock lang="typescript" code={`const agents = await listAgents()
// Returns: [{ filename, name, description, model, body }]
agents.forEach(a => console.log(a.filename, '—', a.description))`} />
              </div>
              <div>
                <p className="text-xs font-semibold text-text-secondary mb-2">isOnline() — health check</p>
                <CodeBlock lang="typescript" code={`const up = await isOnline()
// Returns: true if Claude Hub is reachable, false if not
if (!up) console.warn('Claude Hub is not running')`} />
              </div>
            </div>
          </Collapsible>

          <Collapsible title="Installing SDK in a New Project (Manual Steps)">
            <div className="space-y-3">
              <p className="text-xs text-text-secondary leading-relaxed">If you have a new project not yet in the list above, follow these steps:</p>
              <p className="text-xs font-medium text-text-muted">Step 1 — Add to package.json dependencies:</p>
              <CodeBlock lang="json" code={`"dependencies": {
  "@boldteq/agents": "file:../claude-hub/sdk"
}`} />
              <NoteBox type="warn">
                The path <code className="font-mono text-accent">file:../claude-hub/sdk</code> is relative. It assumes your project is a sibling of claude-hub inside the same parent folder (Boldteq App/). If your folder structure is different, adjust the path.
              </NoteBox>
              <p className="text-xs font-medium text-text-muted">Step 2 — Install:</p>
              <CodeBlock code="npm install" />
              <p className="text-xs font-medium text-text-muted">Step 3 — Verify:</p>
              <CodeBlock code={`node -e "const { isOnline } = require('@boldteq/agents'); isOnline().then(v => console.log('SDK works:', v))"`} />
            </div>
          </Collapsible>
        </div>
      </section>

      {/* ── Section 5: Slash Commands ── */}
      <section>
        <SectionHeader
          icon={Terminal}
          title="Slash Commands"
          subtitle="User-invocable commands — type /name in VS Code Claude Code chat."
        />

        <NoteBox type="info">
          <strong>Agents vs Slash Commands:</strong> Agents (<code className="font-mono text-accent">~/.claude/agents/</code>) are invoked by Claude automatically. Slash commands (<code className="font-mono text-accent">.claude/commands/</code>) are invoked by YOU typing <code className="font-mono text-accent">/commandname</code> in VS Code. Both use <code className="font-mono text-accent">$ARGUMENTS</code> for your input.
        </NoteBox>

        <div className="mt-4 space-y-3">
          <Collapsible title="How Slash Commands Work">
            <div className="space-y-3">
              <p className="text-xs text-text-secondary leading-relaxed">
                Each file in <code className="font-mono text-accent">.claude/commands/</code> becomes a slash command. The filename (without .md) is the command name. When you type <code className="font-mono text-accent">/feature Add bulk CSV import</code>, Claude Code reads <code className="font-mono text-accent">feature.md</code> and replaces <code className="font-mono text-accent">$ARGUMENTS</code> with "Add bulk CSV import".
              </p>
              <CodeBlock lang="markdown" code={`# .claude/commands/mycommand.md

You are an expert at [task].
Given this input: $ARGUMENTS

Do the following:
1. Step one
2. Step two

Output: [describe expected output format]`} />
              <NoteBox type="tip">The more specific your command instructions, the better the output. Always describe the expected output format.</NoteBox>
            </div>
          </Collapsible>

          <Collapsible title="Pinzo's Slash Commands">
            <div className="space-y-4">
              {[
                { cmd: '/feature', file: 'feature.md', desc: 'Build a complete feature end-to-end.', use: '/feature Add bulk CSV import for ZIP codes', detail: 'Reads CLAUDE.md, plans the feature, builds route + DB migration + UI, runs typecheck. Follows all Polaris and auth-first rules.' },
                { cmd: '/fix',     file: 'fix.md',     desc: 'Debug and fix a bug.',                 use: '/fix delivery rules not saving for merchants on free plan', detail: 'Diagnoses root cause, reads relevant files, applies targeted fix, verifies no regressions.' },
                { cmd: '/review',  file: 'review.md',  desc: 'Pre-deploy quality audit.',            use: '/review', detail: 'Runs typecheck, checks auth on every route, checks shop-scoped DB queries, verifies CORS, Polaris compliance, billing gates.' },
                { cmd: '/db',      file: 'db.md',      desc: 'Database utilities.',                  use: '/db show schema for DeliveryRule model', detail: 'Reads schema.prisma, explains models, helps with migrations.' },
              ].map(item => (
                <div key={item.cmd} className="bg-surface-2 rounded-xl p-4 space-y-2">
                  <div className="flex items-center gap-2">
                    <code className="text-sm font-mono font-bold text-accent">{item.cmd}</code>
                    <span className="text-xs text-text-muted">— {item.desc}</span>
                  </div>
                  <p className="text-xs text-text-muted">{item.detail}</p>
                  <CodeBlock code={item.use} />
                </div>
              ))}
            </div>
          </Collapsible>

          <Collapsible title="Adding Global Agents as Slash Commands">
            <div className="space-y-3">
              <p className="text-xs text-text-secondary leading-relaxed">
                You can create slash commands in any project that wrap a global agent. This lets you type <code className="font-mono text-accent">/quill Write App Store listing</code> directly.
              </p>
              <CodeBlock lang="bash" code={`# Location: Pinzo/.claude/commands/quill.md
# Content:`} />
              <CodeBlock lang="markdown" code={`You are Quill, the Content & Copy agent for Boldteq.
[Paste Quill's full instructions here, or reference the key rules]

## Your Task
$ARGUMENTS

Produce the actual deliverable directly. No meta-commentary.`} />
              <NoteBox type="tip">Or keep it simple — just write the task-specific instructions for your project without copying the full agent. The global CLAUDE.md already loads Quill's standards.</NoteBox>
            </div>
          </Collapsible>
        </div>
      </section>

      {/* ── Section 6: Orchestration Quick Reference ── */}
      <section>
        <SectionHeader
          icon={GitBranch}
          title="Orchestration"
          subtitle="Visual DAG workflow builder — chain multiple agents together. Navigate to Orchestration in the sidebar."
        />

        <NoteBox type="info">
          <strong>What it does:</strong> Build a node graph where each node is an agent or custom step. Connect nodes with edges. When you run it, Claude Hub executes them in order — each node receives the outputs of all its upstream nodes as context.
        </NoteBox>

        <div className="mt-4 grid grid-cols-2 gap-4">
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2.5">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3">Key Rules</p>
            {[
              'Start/Task nodes are free — no Claude call',
              'Nodes run in topological order (numbered badges)',
              'Each node gets all upstream outputs as context',
              'Node instructions must produce deliverables, not commentary',
              'Max 120s per node (then timeout)',
              'No circular edges — DAG only',
            ].map(rule => (
              <div key={rule} className="flex items-start gap-2 text-xs text-text-secondary">
                <CheckCircle className="w-3 h-3 text-green shrink-0 mt-0.5" />
                {rule}
              </div>
            ))}
          </div>
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2.5">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3">Node Instructions — Do This</p>
            <div className="space-y-2">
              <p className="text-[11px] text-red font-medium">❌ Bad (produces meta-commentary):</p>
              <CodeBlock code={`"Write about the topic"`} />
              <p className="text-[11px] text-green font-medium">✅ Good (produces deliverable):</p>
              <CodeBlock code={`"Write a complete 400-word blog post intro about the given topic. Output only the post — no explanations."`} />
            </div>
          </div>
        </div>
      </section>

      {/* ── Section 7: PM2 & LaunchAgent Reference ── */}
      <section>
        <SectionHeader
          icon={Settings}
          title="pm2 & LaunchAgent Reference"
          subtitle="Complete command reference for managing Claude Hub as a background service."
        />

        <div className="space-y-4">
          <Collapsible title="pm2 — All Commands" defaultOpen>
            <div className="space-y-3">
              <CodeBlock code={`# Daily use
pm2 status                    # See all running processes
pm2 restart claude-hub        # Restart after changes
pm2 logs claude-hub           # Stream live logs
pm2 logs claude-hub --lines 50 --nostream  # View last 50 log lines

# Setup (first time or after moving files)
cd ~/Desktop/Boldteq\\ App/claude-hub
pm2 start ecosystem.config.js # Register and start
pm2 save                      # Save list (survives reboots)
pm2 startup                   # Generate startup script

# Troubleshooting
pm2 stop claude-hub           # Stop
pm2 delete claude-hub         # Remove from pm2 entirely
pm2 kill                      # Kill pm2 daemon itself`} />
              <NoteBox type="warn">
                <strong>If pm2 shows "errored":</strong> Run <code className="font-mono text-accent">pm2 logs claude-hub</code> to see the error. Most common cause: port 3847 already in use. Fix: <code className="font-mono text-accent">lsof -ti:3847 | xargs kill -9</code> then <code className="font-mono text-accent">pm2 restart claude-hub</code>
              </NoteBox>
            </div>
          </Collapsible>

          <Collapsible title="LaunchAgent — macOS Auto-Start">
            <div className="space-y-3">
              <p className="text-xs text-text-secondary leading-relaxed">
                The LaunchAgent is a macOS system file that tells the OS to start a process when you log in. It's stored at <code className="font-mono text-accent">~/Library/LaunchAgents/io.boldteq.claude-hub.plist</code>.
              </p>
              <CodeBlock lang="bash" code={`# Check if installed
ls ~/Library/LaunchAgents/io.boldteq.claude-hub.plist

# Load (register with macOS — run once after creating the plist)
launchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist

# Verify it's running
launchctl list | grep claude-hub

# Unload (stop and deregister)
launchctl unload ~/Library/LaunchAgents/io.boldteq.claude-hub.plist

# If broken — unload, then reload
launchctl unload ~/Library/LaunchAgents/io.boldteq.claude-hub.plist
launchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist`} />
              <NoteBox type="info">
                The plist file sets the Node.js path, working directory, and environment variables. If you upgrade Node.js via nvm, update the path in the plist and reload it.
              </NoteBox>
              <p className="text-xs font-medium text-text-muted">Current plist location:</p>
              <CodeBlock code="~/Library/LaunchAgents/io.boldteq.claude-hub.plist" />
            </div>
          </Collapsible>

          <Collapsible title="Fresh Machine Setup — Full Sequence">
            <div className="space-y-3">
              <p className="text-xs text-text-secondary leading-relaxed">Complete sequence to set up from zero on a new Mac:</p>
              <CodeBlock code={`# 1. Install Node.js (via nvm recommended)
curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.0/install.sh | bash
nvm install 20 && nvm use 20

# 2. Install Claude Code
npm install -g @anthropic-ai/claude-code
claude  # authenticate

# 3. Install pm2
npm install -g pm2

# 4. Copy claude-hub to ~/Desktop/Boldteq App/claude-hub
cd ~/Desktop/Boldteq\\ App/claude-hub && npm install

# 5. Start Claude Hub
pm2 start ecosystem.config.js
pm2 save

# 6. Set up LaunchAgent (edit plist to use correct node path first)
node_path=$(which node)  # get current node path
# Edit ~/Library/LaunchAgents/io.boldteq.claude-hub.plist
# Replace node path with $node_path
launchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist

# 7. Install SDK in each project
cd ~/Desktop/Boldteq\\ App/Pinzo && npm install
cd ~/Desktop/Boldteq\\ App/Rankora && npm install
# ... repeat for each project

# 8. Verify
open http://localhost:3847
# Setup & Status should show all green`} />
              <NoteBox type="warn">
                <strong>Important:</strong> The LaunchAgent plist hardcodes the Node.js path. On a new machine, the path will be different. Update the plist before loading it — use <code className="font-mono text-accent">which node</code> to get the correct path.
              </NoteBox>
            </div>
          </Collapsible>
        </div>
      </section>

      {/* ── Section 8: Global CLAUDE.md ── */}
      <section>
        <SectionHeader
          icon={BookOpen}
          title="Global CLAUDE.md"
          subtitle="Loaded in every Claude Code session — your identity, build standards, and agent routing."
        />

        <NoteBox type="info">
          <strong>Why it matters:</strong> This is the first thing Claude Code reads in every session, regardless of which project you're in. It defines your identity as Yash / Boldteq founder, your build standards, and tells Claude which agent to use for which task. If this is stale or missing, Claude won't know your standards.
        </NoteBox>

        <div className="mt-4 grid grid-cols-2 gap-4">
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-2">Required Sections</p>
            {[
              'Identity (who you are, mission, model)',
              'Current Stack Patterns (Stack A / B)',
              'Agent Roster (all 12 agents with filenames)',
              'Agent Routing Rules (task → agent mapping)',
              'Build Standards (TypeScript, auth, billing)',
              'Active Projects (name, type, stack, path)',
              'Working With Yash (preferences)',
            ].map(s => (
              <div key={s} className="flex items-start gap-2 text-xs text-text-secondary">
                <CheckCircle className="w-3 h-3 text-green shrink-0 mt-0.5" />
                {s}
              </div>
            ))}
          </div>
          <div className="bg-surface border border-border rounded-xl p-4 space-y-2.5">
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-2">Edit in Claude Hub</p>
            <p className="text-xs text-text-muted leading-relaxed">Navigate to <strong>Global Config → CLAUDE.md</strong> in the sidebar to edit the global CLAUDE.md directly in the browser. Changes save to disk immediately and take effect in the next Claude Code session.</p>
            <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mt-3 mb-2">File Location</p>
            <CodeBlock code="~/.claude/CLAUDE.md" />
          </div>
        </div>
      </section>

      {/* ── Section 9: Troubleshooting ── */}
      <section>
        <SectionHeader
          icon={Shield}
          title="Troubleshooting"
          subtitle="Common issues and exact fixes."
        />

        <div className="space-y-3">
          {[
            {
              problem: 'Port 3847 already in use (EADDRINUSE)',
              cause: 'A previous Claude Hub process is still running and holding the port.',
              fix: 'lsof -ti:3847 | xargs kill -9\npm2 restart claude-hub',
            },
            {
              problem: 'pm2 shows "errored" with restarts',
              cause: 'Process crashed, usually due to port conflict or missing dependencies.',
              fix: 'pm2 logs claude-hub  # read the error\n# If EADDRINUSE: kill the port (above)\n# If MODULE_NOT_FOUND: npm install in claude-hub/',
            },
            {
              problem: 'LaunchAgent not starting on login',
              cause: 'Plist not loaded, wrong Node.js path, or plist syntax error.',
              fix: 'launchctl list | grep claude-hub  # check if registered\n# If not registered:\nlaunchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist\n# If wrong node path:\nwhich node  # get correct path\n# Edit plist ProgramArguments, then reload',
            },
            {
              problem: 'callAgent() returns "Claude Hub not reachable"',
              cause: 'Claude Hub is not running, or running on a different port.',
              fix: 'pm2 status  # check if running\npm2 restart claude-hub  # restart if stopped\ncurl http://localhost:3847/api/setup/status  # verify',
            },
            {
              problem: 'Agents not found (agentCount shows 0)',
              cause: '~/.claude/agents/ directory is missing or empty.',
              fix: 'ls ~/.claude/agents/\n# If missing: re-create the agents/ directory\n# and copy agent .md files from this machine\'s backup',
            },
            {
              problem: 'Orchestration node produces meta-commentary instead of content',
              cause: 'Node instructions are too vague — the agent evaluates instead of producing.',
              fix: 'Edit node instructions to be explicit:\n"Write a complete [X]. Output only the [X] — no explanations."',
            },
            {
              problem: 'Claude Code not picking up global CLAUDE.md changes',
              cause: 'CLAUDE.md is cached for the current session.',
              fix: 'Start a new Claude Code session — it re-reads all .md files on startup.',
            },
          ].map(item => (
            <div key={item.problem} className="bg-surface border border-border rounded-xl p-4 space-y-2">
              <p className="text-sm font-semibold text-red flex items-center gap-2">
                <XCircle className="w-4 h-4 shrink-0" /> {item.problem}
              </p>
              <p className="text-xs text-text-muted"><strong>Cause:</strong> {item.cause}</p>
              <div>
                <p className="text-xs text-text-muted font-medium mb-1.5">Fix:</p>
                <CodeBlock code={item.fix} />
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* ── Section 10: Docs Reference ── */}
      <section>
        <SectionHeader
          icon={BookOpen}
          title="Documentation"
          subtitle="Full guides in claude-hub/docs/ — open in any text editor or VS Code."
        />
        <div className="bg-surface border border-border rounded-xl overflow-hidden">
          {[
            { file: '00-overview.md',       title: 'System Overview',       desc: 'Full architecture, all components, how everything connects' },
            { file: '01-setup.md',           title: 'Setup Guide',           desc: 'Step-by-step from zero — Node, pm2, LaunchAgent, verification' },
            { file: '02-agents.md',          title: 'Agents Reference',      desc: 'All 12 agents, how to create new ones, invocation methods' },
            { file: '03-sdk.md',             title: 'SDK Reference',         desc: '@boldteq/agents API, installation, examples, error handling' },
            { file: '04-slash-commands.md',  title: 'Slash Commands',        desc: 'How to write and use /commands in VS Code' },
            { file: '05-orchestration.md',   title: 'Orchestration Guide',   desc: 'Visual DAG builder, templates, node instructions, troubleshooting' },
            { file: '06-new-project.md',     title: 'Adding a New Project',  desc: 'CLAUDE.md, agents, commands, SDK — full new project checklist' },
            { file: '07-troubleshooting.md', title: 'Troubleshooting',       desc: 'Every common error with cause and fix' },
          ].map((doc, i, arr) => (
            <div key={doc.file} className={`flex items-center gap-4 px-5 py-3.5 hover:bg-surface-2 transition-colors ${i < arr.length - 1 ? 'border-b border-border' : ''}`}>
              <code className="text-[11px] font-mono text-accent bg-accent-muted px-2 py-0.5 rounded shrink-0 w-44">{doc.file}</code>
              <div className="min-w-0">
                <p className="text-sm font-medium">{doc.title}</p>
                <p className="text-xs text-text-muted truncate">{doc.desc}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-3">
          <CodeBlock code="~/Desktop/Boldteq App/claude-hub/docs/" lang="path" />
        </div>
      </section>

    </div>
  )
}

